from typing import TypedDict

from langgraph.graph import END, START, StateGraph

class EtatHorRAGor(TypedDict, total=False):
    question: str
    trouvailles: list[str]
    complements_web: list[str]
    recit: str

def rag_node(etat: EtatHorRAGor) -> dict:
    base = {"alien": "Alien (1979), Ridley Scott : un xénomorphe à bord du Nostromo."}
    cle = next((k for k in base if k in etat["question"].lower()), None)
    return {"trouvailles": [base[cle]] if cle else []}

def scraper_node(etat: EtatHorRAGor) -> dict:
    return {"complements_web": [f"Résultat web pour : {etat['question']}"]}

def narration_node(etat: EtatHorRAGor) -> dict:
    synthese = " ".join(etat.get("trouvailles", []) + etat.get("complements_web", []))
    return {"recit": f"Dans l'obscurité, une rumeur circule… {synthese}"}

def doit_scraper(etat: EtatHorRAGor) -> str:
    return "narration" if etat.get("trouvailles") else "scraper"

g = StateGraph(EtatHorRAGor)
g.add_node("rag", rag_node)
g.add_node("scraper", scraper_node)
g.add_node("narration", narration_node)
g.add_edge(START, "rag")
g.add_conditional_edges("rag", doit_scraper, {"narration": "narration", "scraper": "scraper"})
g.add_edge("scraper", "narration")
g.add_edge("narration", END)
app = g.compile()

print(app.invoke({"question": "Parle-moi d'Alien"})["recit"])
print(app.invoke({"question": "Parle-moi de Midsommar"})["complements_web"])

